/* Apply styles when screen width is 768px or less */
@media (max-width: 768px) {
  body {
    background-color: lightblue;
  }
  .container {
    flex-direction: column;
  }
}

/* min-width: applies from 600px and above (mobile-first) */
@media (min-width: 600px) {
  .container {
    display: flex;
  }
}

/* max-width: applies up to 600px (desktop-first) */
@media (max-width: 600px) {
  .container {
    display: block;
  }
}

/* Base styles for mobile (default) */
.container {
  display: block;
  padding: 10px;
}

/* Styles for tablet and above */
@media (min-width: 768px) {
  .container {
    display: flex;
    padding: 20px;
  }
}

/* Styles for desktop and above */
@media (min-width: 1024px) {
  .container {
    padding: 40px;
  }
}

/* Full screen section */
.hero {
  width: 100vw;
  height: 100vh;
}

/* Responsive font size */
.title {
  font-size: 5vw;
}

/* Square that fits smaller dimension */
.box {
  width: 50vmin;
  height: 50vmin;
}

/* Absolute unit - always 16px, never changes */
p {
  font-size: 16px;
}

/* Relative units - scale based on parent/root */
.parent {
  font-size: 20px;
}
.child {
  font-size: 1.5em; /* = 30px, relative to parent (20px) */
}
html {
